import hashlib

def is_prime(x):
    if x < 2:
        return False
    i = 2
    while i * i <= x:
        if x % i == 0:
            return False
        i += 1
    return True

def keygen(p, q, e=65537):
    assert is_prime(p) and is_prime(q)
    n, phi = p * q, (p - 1) * (q - 1)
    return (n, e), (n, pow(e, -1, phi))

def H(m, n):
    return int.from_bytes(hashlib.sha256(m).digest(), "big") % n

ca_pub, ca_priv = keygen(1000003, 1000033)          # 신뢰 앵커(루트 CA)
rogue_pub, rogue_priv = keygen(1000081, 1000099)    # 아무나 만든 CA

def sign(msg, priv):
    return pow(H(msg, priv[0]), priv[1], priv[0])

def check(msg, sig, pub):
    return pow(sig, pub[1], pub[0]) == H(msg, pub[0])

cert = b"CN=shop.example;pubkey=AAAA"
# 1) CA 개인키로 서명한 인증서는 CA 공개키로 검증된다
good = check(cert, sign(cert, ca_priv), ca_pub)
# 2) 다른 키로 서명한 인증서는 신뢰 앵커의 공개키로 검증하면 실패한다
bad = not check(cert, sign(cert, rogue_priv), ca_pub)
# 3) 내용이 한 글자만 바뀌어도 서명 검증이 깨진다
tamper = not check(b"CN=shop.example;pubkey=BBBB", sign(cert, ca_priv), ca_pub)
# 4) 서명이 유효해도 이름이 접속 대상과 다르면 거부해야 한다 (호스트명 검증은 별도 단계)
other = b"CN=evil.example;pubkey=CCCC"
sig_valid = check(other, sign(other, ca_priv), ca_pub)
host_match = other.decode().split(";")[0].split("=")[1] == "shop.example"
print(good and bad and tamper and sig_valid and not host_match)
